typedef struct {
    char data[LOG_SIZE];
    int valid;
} slot_t;

slot_t buffer[N];
int head = 0;
int tail = 0;
int count = 0;

mutex_t mtx;
cond_t not_full;
cond_t not_empty;

void enqueue(const char *record) {
    mutex_lock(&mtx);
    while (count >= N)
        cond_wait(&not_full, &mtx);
    buffer[tail % N] = *(slot_t *)record;
    tail++;
    count++;
    cond_signal(&not_empty);
    mutex_unlock(&mtx);
}

void dequeue(char *record) {
    mutex_lock(&mtx);
    while (count == 0)
        cond_wait(&not_empty, &mtx);
    *(slot_t *)record = buffer[head % N];
    head++;
    count--;
    cond_signal(&not_full);
    mutex_unlock(&mtx);
}
```

